package co.kr.badara.campsitejournal.test;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import java.util.concurrent.*;
public class ProfileTest extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{waitForIdleSync();String process=Application.getProcessName();int account=process.endsWith(":platform_account_1")?1:process.endsWith(":platform_account_2")?2:0;if(account==0)throw new AssertionError("Wrong process: "+process);final String mine="account"+account,other="account"+(account==1?2:1);final String[] cookie={null};CountDownLatch saved=new CountDownLatch(1);runOnMainSync(()->{CookieManager manager=CookieManager.getInstance();cookie[0]=manager.getCookie("https://profile-check.invalid/");manager.setCookie("https://profile-check.invalid/","camp_profile="+mine+"; Secure; Path=/",ok->{manager.flush();saved.countDown();});});if(cookie[0]!=null&&cookie[0].contains(other))throw new AssertionError("Cookie leaked across profiles");if(!saved.await(5,TimeUnit.SECONDS))throw new AssertionError("Cookie save timed out");
 for(String provider:new String[]{"camfit","thankq","campingtalk","naver"}){String name=account==1?"PlatformAccountOneActivity":"PlatformAccountTwoActivity";Activity activity=startActivitySync(new Intent().setClassName("co.kr.badara.campsitejournal","co.kr.badara.campsitejournal."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("provider",provider).putExtra("history","{}"));waitForIdleSync();if(activity.isFinishing())throw new AssertionError("Platform failed: "+provider);runOnMainSync(()->{try{java.lang.reflect.Field field=Class.forName("co.kr.badara.campsitejournal.PlatformActivity").getDeclaredField("browser");field.setAccessible(true);if(field.get(activity)==null)throw new AssertionError("No WebView");activity.finish();}catch(Exception error){throw new AssertionError(error);}});waitForIdleSync();}
 result.putString("result","PASS");result.putString("profile",mine+" isolated cookies and four platform screens");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("result",error.toString());finish(Activity.RESULT_CANCELED,result);}}
}
